export function reportText({kind,scope,title,url,message,steps,expected}) {
  return `TechAtlas · ${kind==='bug'?'รายงานบั๊ก':'ข้อเสนอแนะ'}\nขอบเขต: ${scope==='lesson'?'บทเรียน':'ทั้งโปรเจกต์'}\nหัวข้อ: ${title}\nหน้า: ${url}\n\nรายละเอียด:\n${message}\n\nขั้นตอนที่พบ:\n${steps||'ไม่ได้ระบุ'}\n\nผลที่คาดหวัง:\n${expected||'ไม่ได้ระบุ'}\n`;
}
export function initFeedback() {
  const dialog=document.createElement('dialog');dialog.className='feedback-dialog';
  dialog.innerHTML=`<button type="button" class="close" aria-label="ปิดแบบฟอร์มรายงาน">×</button><h2>รายงานบั๊ก & ข้อเสนอแนะ</h2><p id="report-context"></p><form><label>ประเภท<select name="kind"><option value="bug">รายงานบั๊ก</option><option value="suggestion">ข้อเสนอแนะ</option></select></label><label>รายละเอียด<textarea name="message" rows="4" maxlength="3000" required placeholder="พบอะไร หรืออยากให้ปรับปรุงอะไร"></textarea></label><label>ขั้นตอนที่พบปัญหา (ถ้ามี)<textarea name="steps" rows="3" maxlength="2000" placeholder="เช่น เปิดบท TCP → กดเล่น → ภาพไม่เปลี่ยน"></textarea></label><label>ผลที่คาดหวัง (ถ้ามี)<textarea name="expected" rows="2" maxlength="1000"></textarea></label><p>ส่งถึง wichitpan.w@gmail.com ผ่านแอปอีเมลของคุณ แนบเฉพาะชื่อบทและลิงก์หน้า ไม่ดึงโค้ดหรือข้อมูลในเครื่องอัตโนมัติ กรุณาไม่ใส่รหัสผ่านหรือข้อมูลบริษัท</p><div class="report-actions"><button type="submit" class="button">เตรียมอีเมลรายงาน</button><button type="button" data-copy class="button light">คัดลอกข้อความ</button></div><p role="status" id="report-status"></p><a hidden id="report-email">เปิดแอปอีเมลเพื่อส่งรายงาน ↗</a><details><summary>ดูข้อความรายงาน</summary><pre id="report-preview"></pre></details></form>`;
  document.body.append(dialog);let context;
  document.addEventListener('click',e=>{
    const button=e.target.closest('[data-report]');if(!button)return;
    context={scope:button.dataset.report,title:button.dataset.report==='lesson'?document.querySelector('main h1')?.textContent||'บทเรียน':'ภาพรวมโปรเจกต์',url:location.origin+location.pathname+location.hash};
    dialog.querySelector('form').reset();dialog.querySelector('#report-email').hidden=true;dialog.querySelector('#report-preview').textContent='';dialog.querySelector('#report-status').textContent='';dialog.querySelector('#report-context').textContent=context.scope==='lesson'?`บทเรียน: ${context.title}`:'รายงานเกี่ยวกับทั้งโปรเจกต์';dialog.showModal();
  });
  dialog.querySelector('.close').onclick=()=>dialog.close();
  const build=()=>{const form=dialog.querySelector('form');if(!form.reportValidity())return null;const data={...context,...Object.fromEntries(new FormData(form))};const text=reportText(data);dialog.querySelector('#report-preview').textContent=text;return {text,data};};
  dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const report=build();if(!report)return;const link=dialog.querySelector('#report-email');link.href=`mailto:wichitpan.w@gmail.com?subject=${encodeURIComponent(`[TechAtlas] ${report.data.kind==='bug'?'บั๊ก':'ข้อเสนอแนะ'} · ${report.data.title}`)}&body=${encodeURIComponent(report.text)}`;link.hidden=false;dialog.querySelector('#report-status').textContent='รายงานพร้อมแล้ว กดลิงก์ด้านล่างและส่งจากแอปอีเมล ยังไม่ได้ส่งหรือบันทึกบนเซิร์ฟเวอร์ หากไม่มีแอปอีเมลให้คัดลอกข้อความไปส่งด้วยตนเอง';};
  dialog.querySelector('[data-copy]').onclick=async()=>{const report=build();if(!report)return;try{await navigator.clipboard.writeText(report.text);dialog.querySelector('#report-status').textContent='คัดลอกแล้ว วางในอีเมลถึง wichitpan.w@gmail.com แล้วส่งได้เลย';}catch{dialog.querySelector('#report-status').textContent='คัดลอกอัตโนมัติไม่ได้ เปิด “ดูข้อความรายงาน” แล้วเลือกคัดลอกด้วยตนเอง';}};
}
